function extractText(json) {
  if (Array.isArray(json.output)) {
    for (const item of json.output) {
      if (item.type === 'message' && Array.isArray(item.content)) {
        const tb = item.content.find(c => c.type === 'output_text' || typeof c.text === 'string');
        if (tb?.text) return tb.text;
      }
    }
  }
  return json.message?.content ?? json.content ?? json.choices?.[0]?.message?.content ?? '';
}

const raw = extractText($json);
let cleaned = raw.replace(/```json|```/g, '').trim();
const m = cleaned.match(/\{[\s\S]*\}/);
if (m) cleaned = m[0];

let reviewer;
try {
  reviewer = JSON.parse(cleaned);
} catch (e) {
  reviewer = { approved: false, contradicts_transcript: true, issues: ['Reviewer output failed to parse — treated as rejected: ' + e.message] };
}

const prior = $('Guardrail Check - Deterministic').item.json;

const finalApproved = prior.guardrail_passed && reviewer.approved && !reviewer.contradicts_transcript;

return [{
  json: {
    ...prior,
    reviewer,
    final_approved: finalApproved
  }
}];

