const ctx = $json;
const p = ctx.proposal;

// Normalize package_selected in case the model appended price/includes text
// instead of returning just the catalog's PACKAGE_NAME value.
p.package_selected = (p.package_selected || '').split(':')[0].split('|')[0].trim();

const catalog = ctx.pricing_catalog_json;
const pkg = catalog.find(row => row.package_name === p.package_selected);

const errors = [];

if (!pkg) {
  errors.push(`Package "${p.package_selected}" is not in the approved catalog`);
} else {
  if (p.quoted_price < Number(pkg.floor_price)) errors.push(`Quoted price ${p.quoted_price} is below floor price ${pkg.floor_price}`);
  if (p.quoted_price > Number(pkg.ceiling_price)) errors.push(`Quoted price ${p.quoted_price} is above ceiling price ${pkg.ceiling_price}`);

  const expectedValidUntil = new Date();
  expectedValidUntil.setDate(expectedValidUntil.getDate() + Number(pkg.valid_days) + 1); // +1 day slack
  if (new Date(p.valid_until) > expectedValidUntil) errors.push(`valid_until ${p.valid_until} exceeds the package's ${pkg.valid_days}-day validity window`);
}

if (!p.body_html || p.body_html.length < 100) errors.push('Proposal body is missing or too short');
if (!p.subject) errors.push('Proposal subject is missing');
if (isNaN(new Date(p.valid_until).getTime())) errors.push('valid_until is not a valid date');

return [{
  json: {
    ...ctx,
    guardrail_errors: errors,
    guardrail_passed: errors.length === 0
  }
}];

